        raw_side=max([abs(s)*1.5 for _,_,s in points]+[5]);side_abs=5 if raw_side<=5 else 10 if raw_side<=10 else 20 if raw_side<=20 else 30
        W,H=1040,390;left,right,top,bottom=54,28,28,58;pw=W-left-right;ph=H-top-bottom
        px=lambda distance:left+(max(0,min(distance_max,distance))/distance_max)*pw
        py=lambda side:top+ph*.5+(max(-side_abs,min(side_abs,side))/side_abs)*ph*.44
