def _public_update_status():
    release=check_for_update(__version__)
    return {k:release[k] for k in ('current_version','latest_version','update_available','release_url','release_name','release_notes','published_at')}|{'can_install':bool(getattr(sys,'frozen',False))}
def _start_background_update():
    if not getattr(sys,'frozen',False):raise UpdateError('Automatic installation is available only in the packaged application.')
    local=os.environ.get('LOCALAPPDATA')
    if not local:raise UpdateError('LOCALAPPDATA is not set.')
    root=Path(local)/'VTrackShotTracker';root.mkdir(parents=True,exist_ok=True)
    flags=subprocess.CREATE_NEW_PROCESS_GROUP|subprocess.DETACHED_PROCESS|subprocess.CREATE_NO_WINDOW if os.name=='nt' else 0
    try:
        with (root/'updater.log').open('a',encoding='utf-8') as out,(root/'updater.error.log').open('a',encoding='utf-8') as err:
            return subprocess.Popen([sys.executable,'update','--yes'],cwd=str(Path(sys.executable).resolve().parent),stdin=subprocess.DEVNULL,stdout=out,stderr=err,creationflags=flags,close_fds=True)
    except OSError as exc:raise UpdateError(f'Could not start updater: {exc}') from exc
