            if p=='/api/preferences':
                try:n=int(self.headers.get('Content-Length','0'));obj=json.loads(self.rfile.read(n) or b'{}')
                except (ValueError,TypeError,json.JSONDecodeError):return self.sendj({'error':'bad json'},400)
                try:return self.sendj({'ok':True,'preferences':store.save_ui_preferences(obj)})
                except ValueError as exc:return self.sendj({'error':str(exc)},413)
