def main(argv: Optional[list[str]]=None):
    ap=argparse.ArgumentParser()
    ap.add_argument('--db',type=Path,default=Path.home()/'Documents'/'VTrackArchive'/'vtrack_shots.sqlite3')
    ap.add_argument('--port',type=int,default=8765)
    ap.add_argument('--no-browser',action='store_true')
    ap.add_argument('--dev',action='store_true')
    a=ap.parse_args(argv)

    # Shot Review must be usable on a clean install, even before the collector
    # has ever run or VTrack is installed/running.
    a.db=a.db.expanduser().resolve()
    a.db.parent.mkdir(parents=True,exist_ok=True)
    initializer=Database(a.db)
    initializer.close()

    store=ShotStore(a.db)
    srv=ThreadingHTTPServer(('127.0.0.1',a.port),make_handler(store,a.dev))
    url=f'http://127.0.0.1:{a.port}/'
    print(APP_TITLE)
    print(url)
    if not a.no_browser:threading.Timer(.4,lambda:webbrowser.open(url)).start()
    try:srv.serve_forever()
    except KeyboardInterrupt:pass
    finally:srv.server_close()
    return 0
if __name__=='__main__':raise SystemExit(main())
